{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Absolute bioavailability of a 25 mg tablet in fasted humans was 71.64% (90% CI 64.28–79.84) versus IV microtracer infusion, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Absolute bioavailability of trametinib 2 mg tablet versus IV microtracer was 72.3% (range 45.7–92.8%), well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Absolute bioavailability of nevirapine oral solution versus IV infusion was 91 ± 8% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-scoring direct absolute bioavailability records in humans (71.64%, 72.3%, 91%) all exceed 20%; no affirmative low-bioavailability evidence transfers to the query.",
  "evidence_gaps": [
    "Molecule 3 contains records for different named agents (ORH-2014 and TSU-68), so its cards were discounted as a provenance conflict.",
    "Molecule 4 groups posaconazole, voriconazole, amphotericin B, and Uniphyl; inconsistent provenance prevents use of those records.",
    "Molecule 5 groups pethidine/meperidine and morphine; inconsistent provenance prevents use of those records.",
    "Molecule 9's F = 0.27 was relative to intramuscular rather than IV, so it is less direct for absolute oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

